                    && ll.heap_id().is_none()


                    && delay_token.instance_id() == instance@.id()
                    && delay_token.key() == page_id


                    && v as int == ll.ptr() as int + delay_token.value().to_int()

                    && ll.ptr() as int % 4 == 0

